<script setup lang="ts">
import * as echarts from 'echarts'
import { onBeforeUnmount,onMounted,ref,watch } from 'vue'
import type { WeatherDTO } from '../lib/liveData'
const props=defineProps<{weather:WeatherDTO}>(); const node=ref<HTMLDivElement>(); let chart:echarts.ECharts|undefined
function draw(){if(!chart)return; const rows=props.weather.series; chart.setOption({animation:false,tooltip:{trigger:'axis'},legend:{data:['Температура','Волога 0–1 см','Волога 1–3 см','Опади']},grid:{left:54,right:118,top:64,bottom:58},xAxis:{type:'category',data:rows.map(row=>new Date(row.time).toLocaleTimeString('uk-UA',{timeZone:'UTC',hour:'2-digit',minute:'2-digit'})),axisLabel:{rotate:30}},yAxis:[{type:'value',name:'°C'},{type:'value',name:'м³/м³',position:'right',offset:62,min:0,max:1},{type:'value',name:'мм',position:'right',min:0}],series:[{name:'Температура',type:'line',data:rows.map(row=>row.temperature_2m),itemStyle:{color:'#215f4b'}},{name:'Волога 0–1 см',type:'line',yAxisIndex:1,data:rows.map(row=>row.soil_moisture_0_to_1cm),itemStyle:{color:'#537d62'}},{name:'Волога 1–3 см',type:'line',yAxisIndex:1,data:rows.map(row=>row.soil_moisture_1_to_3cm),itemStyle:{color:'#77947c'}},{name:'Опади',type:'bar',yAxisIndex:2,data:rows.map(row=>row.precipitation),itemStyle:{color:'#719bb7'}}]},true)}
const resize=()=>chart?.resize(); onMounted(()=>{if(node.value&&node.value.clientWidth>0){chart=echarts.init(node.value);draw();window.addEventListener('resize',resize)}}); watch(()=>props.weather,draw,{deep:true});onBeforeUnmount(()=>{window.removeEventListener('resize',resize);chart?.dispose()})
</script>
<template><div><div ref="node" class="chart" role="img" aria-label="Почасові модельні температура, волога ґрунту та опади"></div><dl class="accessible"><div v-for="row in weather.series" :key="row.time"><dt>{{ row.time }}</dt><dd>Температура {{ row.temperature_2m ?? '—' }} °C; волога 0–1 см {{ row.soil_moisture_0_to_1cm ?? '—' }} м³/м³; опади {{ row.precipitation ?? '—' }} мм</dd></div></dl></div></template>
<style scoped>.chart{height:360px;width:100%}.accessible{font-size:13px}.accessible div{margin:4px 0}.accessible dt{font-weight:600}.accessible dd{margin:0}</style>
